LANG = 'rod'
SENTENCES = {
    'b1-dr1': ['Tha mi', 'ag ionnsachadh', 'stiùireadh-carbaid'],
    'b1-dr2': ['Mar as trice,', 'dùiscidh mi', 'tràth'],
    'b1-dr3': ['An-dè,', 'ghlan mi', 'an taigh', 'gu lèir'],
    'b1-dr4': ['Cha do chaill mi', 'aon latha', 'obrach', 'a-riamh'],
    'b1-fs1': ['Cha bhi mo bhràthair', "a' cluich", 'spòrs'],
    'b1-fs2': ['Bu chòir dhuinn', 'guth-sreinge a chur', 'gu ar', 'pàrantan'],
    'b1-fs3': ["Am b' urrainn dhuibh", 'mo chuideachadh', 'le seo,', 'mas e ur toil e?'],
    'b1-fs4': ['Tha', 'mo phiuthar', 'nas bruidhniche', 'na mise'],
    'b1-te1': ['An-dè,', 'thadhail mi', 'air cathair', 'ùr'],
    'b1-te2': ['Ma bhios an t-uisce ann,', 'fuirichidh sinn', 'anns an taigh-òsta'],
    'b1-te3': ['Cha robh mi', 'a-riamh', 'anns an t-Seapan'],
    'b1-te4': ['An urrainn dhut', 'deagh thaigh-òsta', 'a mholadh?'],
    'b1-op1': ['Tha an ceòl', 'glè', 'labhar'],
    'b1-op2': ["Tha a' chathair seo", 'nas daoire', 'na', 'an tè ud'],
    'b1-op3': ["Tha mi a' smaoineachadh", 'gu bheil an leabhar seo', 'glè', 'inntinneach'],
    'b1-op4': ['Nam bheachd-sa,', 'bu chòir dhuinn', 'falbh', 'tràth'],
    'c2-s01': ['Leis an fhìrinn innse,', 'bhithinn air smaoineachadh', 'dà thuras', "mus cuirinn m' ainm", 'ri rud mar sin'],
    'c2-s02': ['Chan e', 'nach eil diù agam —', "'s e", 'nach eil dad air fhàgail agam', 'ri thoirt seachad'],
    'c2-s03': ["Ge b' e dè a nì thu,", 'na leig leis', 'ìmpidh a chur ort', 'a dhèanamh'],
    'c2-s04': ['Nam biodh fios agam', 'gun sìneadh e a-mach', 'cho fada seo,', 'cha bhithinn a-riamh', 'air aontachadh'],
    'c2-s05': ['Rinn i beag dheth,', 'ach bha e follaiseach', 'gun do ghoill e', 'oirre'],
    'c2-s06': ['Abair na thogras tu', 'mu a dheidhinn,', 'ach', 'gheibh esan', 'rudan dèanta'],
    'c2-s07': ['Chan eil dùil agam', 'mo leisceul a ghabhail', 'airson rud', 'nach do rinn mi', 'idir'],
    'c2-s08': ['Mun àm a fhuair iad', 'mu dheireadh', 'gu a chàradh,', 'bha am milleadh', 'dèanta mu thràth'],
    'c2-s09': ['Eadar mise is tusa,', "chan eil mi a' smaoineachadh", 'gun tèid', 'an cùmhnant', 'air adhart'],
    'c2-s10': ['Shaoileadh tu', 'gum biodh iad', 'air ionnsachadh', 'ron àm seo,', 'nach saoileadh?'],
    'c2-s11': ['Cha bu luaithe', 'a shuidh sinn sìos', 'na', 'sheirm', 'an clag-teine'],
    'c2-s12': ['Mura h-eil', 'e gu diofar dhut,', "b' fheàrr leam", 'gun cumadh sinn seo', 'eadarainn fhèin'],
    'c1-m01': ["Dh'ainmich", 'an riaghaltas', 'ceumannan ùra', 'gus an lobhadh-airgid', 'a lùghdachadh'],
    'c1-m02': ['A rèir an iomraidh,', 'thuit', 'cion-cosnaidh', 'airson an treas mìos', 'an dèidh a chèile'],
    'c1-m03': ['Cha tuirt mi a-riamh', "gun robh mi a' falbh;", 'thuirt mi', 'gun robh feum agam', 'air ùine'],
    'c1-m04': ["Ge b' e dè a thachras", 'a-nochd,', 'na foscail', 'an doras sin'],
    'c1-m05': ['Tha rannsaichean-dùile', "a' toirt rabhaidh", 'gum faodadh an eigh-shruth', 'a dhol à sealladh', 'taobh a-staigh deichead'],
    'c1-m06': ['Nan robh thu', 'air an fhìrinn innse dhomh,', 'cha bhiodh', 'dad de seo', 'air tachairt'],
    'c1-m07': ['Chaidh an neach fo amharas', 'a chur an grèim', 'goirid an dèidh', 'do luchd na faire', 'fios gun ainm fhaighinn'],
    'c1-m08': ['Leis an fhìrinn innse,', "tha mi a' smaoineachadh", "gu bheil a' choire oirnn le chèile", 'airson na thachair'],
    'c1-m09': ["Chaidh a' chompanaidh", 'às àicheadh', 'nan casaidean,', 'ach dhiùlt i', 'tuilleadh beachd a thoirt'],
    'c1-m10': ["Chan eil dad a dh'fhios agad", 'dè a leig mi seachad', 'airson faighinn', 'an-seo'],
    'c1-m11': ['Thèid na taghadairean', 'gu na h-ionadan-taghaidh', 'Didòmhnaich,', 'am measc mì-chinnt', "a tha a' sìor fhàs"],
    'c1-m12': ['Canamaid dìreach', 'nach deach cùisean', 'mar a bha', 'dùil agam'],
}
DIALOGUES = {
    'd-a2-01': ['Dia dhuibh, is mise Marta. Tha mi toilichte coinneachadh ribh.', 'Tha mi toilichte coinneachadh ribh cuideachd, is mise Alex.', 'Chan eil, gu robh math agaibh.', 'Tha e air an làimh dheis.', 'Tha e trì uairean.'],
    'd-a2-02': ['Cò às a tha sibh?', 'Is ann à Chicago a tha mi, anns na Stàitean Aonaichte.', "Tha mi fichead bliadhna a dh'aois.", 'Is toil leam cofaidh.', 'Tha mi ag obair ann am banca.'],
    'd-a2-03': ["Dè an obair a th' agaibh?", "Is e dealbhaiche a th' annam, tha mi ag obair bhon taigh.", "Tha mi a' fuireach faisc air a' phàirc.", 'Is fheàrr leam tì.', 'Bidh an t-uisce ann a-màireach.'],
    'd-a2-04': ["Dè cho fada 's a tha sibh air a bhith an-seo?", 'Tha mi air a bhith an-seo dà mhìos.', "Tha e a' cosc deich iùro.", 'Bidh e dùinte Didòmhnaich.', 'Tha dithis bhràithrean agam.'],
    'd-a2-05': ['A bheil bràithrean no peathraichean agaibh?', 'Tha, tha piuthar as sine agam.', 'Tha, aig ochd uairean.', 'Chan eil, tha e glè dhaor.', "Tha e anns a' chidsin."],
    'd-a2-06': ['Gu robh math agad airson tighinn, chì mi a-rithist thu!', 'Gu robh math agadsa, bha e mìorbhaileach! Chì mi a-rithist thu.', 'Bu toil leam cofaidh.', "Tha mi duilich, chan eil mi a' tuigsinn.", 'Tha an taigh-beag thall an-siud.'],
    'd-a2-07': ['Tha e glè fhuar an-diugh, nach eil?', "Tha gu dearbh, glè fhuar. Agus tha iad ag ràdh gum bi sneachd ann a-màireach.", "Tha, is e Alex an t-ainm a th' orm.", 'Chan eil, chan eil bràithrean agam.', "Tha e a' cosc còig iùro."],
    'd-a2-08': ["Dè a tha sibh a' dèanamh aig an deireadh-seachdain?", "Tha mi a' dol a thadhal air mo phàrantan.", 'Tha mi ag obair ann an oifis.', 'Tha e air an làimh chlì.', 'Is fheàrr leam an dath dearg.'],
    'd-a2-09': ['Dè mu dheidhinn cofaidh a-màireach?', 'Gu dearbh! A bheil deich uairean freagarrach dhut?', 'Is ann à Madrid a tha mi.', 'Tha cù agam.', "Tha an t-uisce a' dòrtadh."],
    'd-a2-10': ['Cuin a thòisicheas an sceul-scàile?', "Tòisichidh e aig leth-uair an dèidh seachd.", 'Tha e glè fhada air falbh.', 'Chòrd e rium gu mòr.', "Is e oileanach a th' annam."],
    'd-a2-11': ['Ciamar a chaidh an latha agad an-diugh?', 'Gu math, ach tha mi scìth.', 'Tha e dà iùro.', "Tha mi a' fuireach air an treas làr.", 'Sin mo phiuthar.'],
    'd-a2-12': ["Càite a bheil sibh a' dol?", 'Don mhargadh-mullaich, chan eil dad agam airson na suipeire.', "Tha mi deich bliadhna fichead a dh'aois.", 'Tha e glè theth.', 'Tha, tha beagan agam.'],
    'd-b1-01': ["Chan fhaca mi thu o chionn fhada! Dè a tha thu air a bhith a' dèanamh o chionn ghoirid?", "Dh'atharraich mi m' obair o chionn dà mhìos agus tha mi glè thoilichte.", 'Falbhaidh an carbad-iarainn aig naoi uairean.', 'Is fheàrr leam tì na cofaidh.', 'Tha e dà shràid air falbh.'],
    'd-b1-02': ["Tha mi air a bhith fo chuideam mòr leis an obair o chionn ghoirid.", 'Tha mi duilich sin a chluinntinn. A bheil thu airson bruidhinn mu dheidhinn?', 'Cheannaich mi each-cuibhle ùr.', 'Tòisichidh an sceul-scàile aig ochd uairean.', "Tha mo phiuthar a' fuireach anns an Ròimh."],
    'd-b1-03': ['Ciamar a chaidh an turas? Innis dhomh a h-uile càil!', 'Bha e mìorbhaileach. Am biadh, na daoine... tha mi airson tilleadh mu thràth.', 'Feumaidh mi bainne a cheannach.', 'Bidh mi ag obair bho naoi gu còig.', 'Bidh e fuar anns an Fhaoilleach.'],
    'd-b1-04': ['Dhealaich Lucia agus mise an t-seachdain sa chaidh.', "Obh obh, cha robh fios agam. Ciamar a tha thu a' faireachdainn a-nis?", 'Meal do naidheachd! Is e deagh naidheachd a tha sin.', 'Cuin a choinnicheas sinn?', 'Bidh an taigh-tascaidh dùinte Diluain.'],
    'd-b1-05': ["A bheil thu fhathast a' dol don talla-neirt?", "Leis an fhìrinn innse, scuir mi. Bidh mi a' ruith sa mhadainn a-nis.", 'Tha, tha an t-aran glè mhath.', "Tha mi a' fuireach air a' chòigeamh làr.", "Is e Dimàirt a th' ann a-màireach."],
    'd-b1-06': ["An do choimhead thu air an t-sreath a mhol mi? Dè do bheachd?", 'Bha mi an grèim bhon chiad earrann, ged a bha an deireadh caran tàmailteach.', "Tha e a' cosc fichead iùro.", 'Tha dà chat agam.', "Tha an taigh-beag aig a' chùl."],
    'd-b1-07': ['Dè mu dheidhinn coiseachd nam beann Disathairne?', "Chan urrainn dhomh Disathairne, tha banais agam. A bheil Didòmhnaich freagarrach dhut?", "Tha, is e Alex an t-ainm a th' orm.", 'Tha an lòchran-stad dearg.', 'Tha am fìon seo à Sìle.'],
    'd-b1-08': ['Tha mi duilich, bidh mi cairteal na h-uarach fadalach.', 'Na gabh dragh, fuirichidh mi riut anns an taigh-cofaidh air an oisean.', 'Is toil leam an dath gorm.', 'Tha e glè ghaothach an-diugh.', "Tha mo cho-là-breith anns a' Chèitean."],
    'd-b1-09': ['An roinn sinn an cunntas, no am pàigh mise an turas seo?', 'Roinneamaid e, ach an ath thuras is e mise a phàigheas.', 'Tha an t-uisce ann a-rithist.', 'Rugadh mi ann an Chicago.', "Bidh an carbad-sluaigh a' tighinn a h-uile deich mionaidean."],
    'd-b1-10': ['An urrainn dhut mo chuideachadh le imrich Diardaoin?', 'Gu dearbh, faodaidh tu earbsa a chur annam. Bidh mi deiseil den obair aig sia uairean, a bheil sin ceart gu leòr?', "Tha an càise anns a' chùil-reothaidh.", "Tha mi air a bhith ag ionnsachadh Seapanais fad bliadhna.", 'Tha an tràigh fada air falbh.'],
    'd-b1-11': ['Dè mu dheidhinn dìnnear aig an taigh-bìdh feòla ùr?', "Leis an fhìrinn innse, is e luibh-itheach a th' annam. A bheil thu eòlach air àite le barrachd roghainn?", 'Bidh leasan cruit-ùird agam gach Diluain.', 'Tha an rathad dùinte.', "Tha m' athair na lighiche."],
    'd-b1-12': ['An toir thu dhomh caogad iùro air iasad gu Dihaoine?', "'S urrainn, gun dragh. Cuiridh mi thugad e an-dràsta.", 'Is fheàrr leam suidheachan ri taobh na h-uinneige seach suidheachan-trannsa.', "Tha a' ghrian a' deàrrsadh aig an tràigh.", "Tha mo sheanmhair ceithir fichead bliadhna a dh'aois."],
    'd-b2-01': ["Tha mi a' smaoineachadh gu bheil obair bhon taigh a' dèanamh cron air obair-scioba.", "Chan eil mi cho cinnteach. Bho m' eòlas fhèin, le deagh bhuill-acainn obraichidh an scioba a cheart cho math, no nas fheàrr.", "Tha an t-iomradh anns a' phascan ghorm.", 'Is fheàrr leam cofaidh gun siùcar.', 'Bidh stad-oibre air na carbadan-iarainn a-màireach.'],
    'd-b2-02': ['Tha an lìon-còmhraidh gar fàgail nas aonranaiche.', 'Ann am pàirt, ach chuidich e mòran dhaoine cuideachd gus coimhearsnachdan a lorg nach robh aca faisc air làimh.', 'Tha ochd litrichean anns an fhacal-fhaire agam.', 'Dùinidh an taigh-bìdh sin aig aon uair deug.', 'Cheannaich mi na bileagan-turais an-dè.'],
    'd-b2-03': ["A bheil sibh a' smaoineachadh gum bu chòir toirmeasc a chur air carbadan-rathaid ann am meadhan a' bhaile?", "Tha, fhad 's a thèid na carbadan-pobaill a leasachadh; air neo, cha dèan e ach an duilgheadas a ghluasad gu nàbachdan eile.", "Tha meadhan a' bhaile deich mionaidean air chois.", 'Tha an carbad-rathaid agam dearg.', 'Cha bhi mi ag obair air Didòmhnaich.'],
    'd-b2-04': ['Tha e do-dhèanta sia cànanan ionnsachadh aig an aon àm.', "Tha e doirbh, tha, ach chan eil e do-dhèanta: tha na cànanan Ròmanach a' neartachadh a chèile, agus tha mòran shamhlaidhean aig Seapanais is Sìnis ann an coitcheann.", 'Tha e fichead ceum an-diugh.', 'Tha coinneamh agam leis an fhiaclair.', 'Ràinig am pascan Diardaoin.'],
    'd-b2-05': ['Thèid am màl suas fichead sa cheud an ath mhìos.', "Tha mi a' tuigsinn gu bheil coscaisean air èirigh, ach is e tòrr a th' ann am fichead sa cheud. Am b' urrainn dhuinn aontachadh air deich sa cheud agus an cùmhnant a leudachadh gu dà bhliadhna?", 'Tha an seòmar-ionnlaid aig ceann an trannsa.', 'Is toil leam an sealladh às an-seo gu mòr.', "Is e mo cho-là-breith a th' ann an-diugh."],
    'd-b2-06': ['Bidh an obair dà sheachdain air dheireadh.', "Dè dìreach an t-adhbhar? Tha feum agam air ceann-latha cinnteach airson innse do na gabhaltaichean.", 'Tha na leacan liath.', 'Tha mi ag obair ann an reic thaighean.', 'Tha bùth-chungaidhean air an oisean.'],
    'd-b2-07': ['Tha mi duilich, chaidh an t-iarrtas agaibh airson ais-dhìoladh a dhiùltadh.', "A rèir ur poileasaidh fhèin, tha trithead latha agam airson a thilleadh, agus chan eil ach dà latha dheug air a dhol seachad. Cò ris am faod mi bruidhinn airson an co-dhùnadh seo ath-scrùdadh?", 'Bu toil leam bòrd airson ceathrar.', "Tha mi a' fuireach faisc air an abhainn.", 'Tha mo bhràthair na innleadair.'],
    'd-b2-08': ["Bha an ceòl agaibh ro àrd a-raoir, cha b' urrainn dhomh cadal.", 'Tha sibh gu tur ceart, tha mi glè dhuilich. Bhon seo a-mach ìslichidh mi e an dèidh deich uairean.', 'Fosclaidh am margadh-mullaich aig ochd uairean.', 'Is toil leam an cù agaibh gu mòr.', 'Tha mi ag ionnsachadh Eadailtis.'],
    'd-c2-01': ["Nach tu a chuir an carbad-rathaid na stad gu snasail! An d' fhuair thu do chead-stiùiridh ann an crannchur?", 'Co-dhiù tha carbad-rathaid agamsa; thàinig thusa air scùtair.', 'Tha mi glè dhuilich, cha tachair e a-rithist.', 'Tha an carbad-rathaid gorm.', 'Tha e glè theth an-diugh.'],
    'd-c2-02': ['Bheirinn buaidh ort ann an rud sam bith, tagh thusa.', "Ceart ma-thà: chì sinn cò as fhaide a mhaireas gun sùil a thoirt air a' ghuth-làimhe.", 'Tha thu ceart, tha thu nas fheàrr na mise anns a h-uile càil.', "Tòisichidh a' cho-fharpais aig ochd uairean.", "Tha mo phiuthar a' fuireach ann an Sevilla."],
    'd-c2-03': ['A bheil an guth-làimhe sin fhathast ag obair? Buinidh e do thaigh-tascaidh.', 'Èist, tha am fear agamsa de sheann linn, chan ann bho fheum.', 'Tha, bu chòir dhomh fear ùr a cheannach a-màireach fhèin.', 'Bidh an taigh-tascaidh dùinte Diluain.', 'Tha feum agam air tobar-dealain.'],
    'd-c2-04': ['Uill, chan eil e dona, airson rud a rinn thusa.', 'Bho chuideigin a loisceadh an t-uisce fhèin, gabhaidh mi sin mar fhacal molaidh.', 'Gu robh math agad, tha mi toilichte gun do chòrd e riut.', "Tha an salann air a' bhòrd.", 'Ghabh mi mo shuipear aig naoi uairean.'],
    'd-c2-05': ['Tha an lìon-còmhraidh air an deasbad poblach a mhilleadh, sin e.', 'Tha cuid den choire air, tha, ach roimhe sin bha an deasbad fo smachd dòrlach de dhuilleagan-naidheachd.', "Tha mi ag aontachadh gu tur, chan eil an còrr ri ràdh.", "Tha mìle neach-leanmhainn aig a' chunntas agam.", 'Thig an duilleag-naidheachd sa mhadainn.'],
    'd-c2-06': ["Chan eil an òigridh an-diugh ag iarraidh obair a dhèanamh, sin agad e.", 'No an e nach eil iad ag iarraidh obair airson tuarastal nach pàigh fiù am màl?', 'Tha thu ceart, tha sinn leisc.', 'Tha mi ag obair ann an oifis.', "Pàighear am màl air a' chiad latha den mhìos."],
    'd-c2-07': ["Bu chòir toirmeasc a chur air carbadan-rathaid ann am meadhan a' bhaile gu lèir, gun eisceachd.", "Chan ann gun eisceachd: dè mu na carbadan-eiridinn, an lìbhrigeadh, daoine aig nach eil comas-gluasaid slàn?", 'Seadh, cuireamaid toirmeasc air a h-uile càil a-màireach.', 'Tha an carbad-rathaid agam dearg.', "Tha mòran bhùthan ann am meadhan a' bhaile."],
    'd-c2-08': ["Chan eil ciall ann a bhith ag ionnsachadh chànanan tuilleadh, eadar-theangaichidh a' chiall-iarainn a h-uile càil.", 'Eadar-theangaichidh i faclan, eadar-theangaichidh; ach am fealla-dhà, an gleus, agus earbsa an duine eile, chan eadar-theangaich duine sin dhut.', 'Tha thu ceart, fàgaidh mi an cùrsa an-diugh fhèin.', 'Tha an innleachd-clàir an-ascaidh.', 'Bidh mi ag ionnsachadh Spàinntis gach Dimàirt.'],
}
